package main

import (
	"encoding/json"
	"net/http"
	"sync"
)

type Job struct {
	ID     string `json:"id"`
	GPUs   int    `json:"gpus"`
	Status string `json:"status"`
}

type JobStore struct {
	mu   sync.Mutex
	jobs map[string]*Job
}

func NewJobStore() *JobStore {
	return &JobStore{
		jobs: make(map[string]*Job),
	}
}

func (s *JobStore) Add(job *Job) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.jobs[job.ID] = job
	s.updateMetrics()
}

func (s *JobStore) GetAll() []*Job {
	s.mu.Lock()
	defer s.mu.Unlock()
	jobs := make([]*Job, 0, len(s.jobs))
	for _, job := range s.jobs {
		jobs = append(jobs, job)
	}
	return jobs
}

func (s *JobStore) QueuedCount() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	count := 0
	for _, job := range s.jobs {
		if job.Status == "queued" {
			count++
		}
	}
	return count
}

func (s *JobStore) updateMetrics() {
	queued := s.QueuedCount()
	gpuJobQueueLength.Set(float64(queued))

	// Calculate GPU utilization: sum of GPUs for queued jobs / total GPUs (assume 8 total)
	s.mu.Lock()
	totalGPUs := 0
	for _, job := range s.jobs {
		if job.Status == "queued" {
			totalGPUs += job.GPUs
		}
	}
	s.mu.Unlock()

	const maxGPUs = 8
	if maxGPUs > 0 {
		utilization := float64(totalGPUs) / float64(maxGPUs) * 100
		gpuUtilizationPercent.Set(utilization)
	}
}

var store = NewJobStore()

func registerRoutes(mux *http.ServeMux) {
	mux.HandleFunc("POST /jobs", handlePostJobs)
	mux.HandleFunc("GET /jobs", handleGetJobs)
}

func handlePostJobs(w http.ResponseWriter, r *http.Request) {
	var job Job
	if err := json.NewDecoder(r.Body).Decode(&job); err != nil {
		http.Error(w, "invalid JSON", http.StatusBadRequest)
		return
	}

	if job.ID == "" {
		http.Error(w, "missing id", http.StatusBadRequest)
		return
	}

	if job.GPUs <= 0 {
		http.Error(w, "gpus must be positive", http.StatusBadRequest)
		return
	}

	job.Status = "queued"
	store.Add(&job)

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(job)
}

func handleGetJobs(w http.ResponseWriter, r *http.Request) {
	jobs := store.GetAll()
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(jobs)
}
